//! Parity of the widget's pure layout with fixtures generated by the real Python `widget` module
//! (tools/gen_fixtures_widget.py -> tests/fixtures/widget.json).

use cu_core::config::{defaults, Config};
use cu_core::widget::*;
use serde_json::{json, Value};
use std::fs;
use std::path::PathBuf;

const NAMES: [&str; 14] = [
    "default",
    "claude-team-01",
    "claude-team-02",
    "claude-ngoai",
    "claude-super-long-account-name",
    "work",
    "claude-a",
    "claude-b",
    "claude-c",
    "claude-d",
    "claude-e",
    "claude-f",
    "claude-g",
    "claude-h",
];

fn prof(i: usize, kind: &str) -> Value {
    match kind {
        "err" => json!({"err": "http 500", "status": 500}),
        "wait" => json!({"err": "429", "status": 429, "five": 10.0, "week": 20.0}),
        _ => {
            json!({"five": ((i * 17) % 100) as f64, "week": ((i * 29) % 100) as f64,
            "five_reset": "2099-01-01T00:00:00+00:00", "week_reset": "2099-01-05T00:00:00+00:00"})
        }
    }
}

fn load() -> Value {
    let p = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/widget.json");
    serde_json::from_str(&fs::read_to_string(p).unwrap()).unwrap()
}

fn f(v: &Value) -> f64 {
    v.as_f64().unwrap()
}

#[test]
fn layout_matches_python() {
    let fx = load();
    let cases = fx["layout"].as_array().unwrap();
    assert!(cases.len() > 1000);
    for (idx, c) in cases.iter().enumerate() {
        let mut cfg: Config = defaults();
        for (k, v) in c["cfg"].as_object().unwrap() {
            cfg.insert(k.clone(), v.clone());
        }
        let ctx = format!("case {idx}: {c}");
        let n = c["n"].as_u64().unwrap() as usize;
        let kinds: Vec<&str> = c["kinds"]
            .as_array()
            .unwrap()
            .iter()
            .map(|k| k.as_str().unwrap())
            .collect();
        let mut profs = serde_json::Map::new();
        for (i, name) in NAMES.iter().take(n).enumerate() {
            profs.insert(
                name.to_string(),
                prof(i, kinds.get(i).copied().unwrap_or("ok")),
            );
        }
        let cache = json!({"ts": 1.0, "profiles": profs, "busy": []});
        let scale = f(&c["scale"]);
        let vertical = c["vertical"].as_bool().unwrap();
        let thick = f(&c["thick"]);
        let docked = c["docked"].as_bool().unwrap();

        // shows / metrics / reset_lines
        let sh = shows(&cfg);
        let want = &c["shows"];
        assert_eq!(
            json!({"label": sh.label, "s5": sh.s5, "s7": sh.s7, "r5": sh.r5, "r7": sh.r7}),
            *want,
            "{ctx}"
        );
        let ms: Vec<Value> = metrics(&cfg)
            .iter()
            .map(|(a, b, c)| json!([a, b, c]))
            .collect();
        assert_eq!(Value::Array(ms), c["metrics"], "{ctx}");
        let rs: Vec<Value> = reset_lines(&cfg)
            .iter()
            .map(|(a, b)| json!([a, b]))
            .collect();
        assert_eq!(Value::Array(rs), c["reset_lines"], "{ctx}");

        let items = visible_profiles(&cfg, Some(&cache));
        let names: Vec<&str> = items.iter().map(|i| i.0.as_str()).collect();
        let want_names: Vec<&str> = c["names"]
            .as_array()
            .unwrap()
            .iter()
            .map(|x| x.as_str().unwrap())
            .collect();
        assert_eq!(names, want_names, "{ctx}");

        let limit = stack_limit(&cfg, vertical, docked, (1920, 1080));
        assert_eq!(limit, c["limit"].as_i64().unwrap(), "{ctx}");
        let (size, shown) = plan_layout(&cfg, &items, scale, vertical, thick, limit, None);
        assert!(
            (size - f(&c["size"])).abs() < 1e-9 && shown == c["shown"].as_u64().unwrap() as usize,
            "{ctx}: got size={size} shown={shown}"
        );
        let view = apply_plan(&items, shown);
        let vnames: Vec<&str> = view.iter().map(|i| i.0.as_str()).collect();
        let want_view: Vec<&str> = c["view"]
            .as_array()
            .unwrap()
            .iter()
            .map(|x| x.as_str().unwrap())
            .collect();
        assert_eq!(vnames, want_view, "{ctx}");

        let real: Vec<String> = view
            .iter()
            .filter(|i| i.0 != MORE)
            .map(|i| i.0.clone())
            .collect();
        let d = cell_dims(&cfg, &real, view.len(), scale, vertical, thick, size);
        let w = c["dims"].as_array().unwrap();
        assert!(
            d.w == w[0].as_i64().unwrap()
                && d.h == w[1].as_i64().unwrap()
                && (d.cw - f(&w[2])).abs() < 1e-9
                && (d.ch - f(&w[3])).abs() < 1e-9,
            "{ctx}: got {d:?}"
        );
    }
}

#[test]
fn misc_matches_python() {
    let fx = load();
    let m = &fx["misc"];
    let base = defaults();
    for r in m["pct_color"].as_array().unwrap() {
        let c = pct_color(f(&r[0]), &base);
        assert_eq!(json!(c), r[1]);
    }
    for r in m["cell_fill"].as_array().unwrap() {
        let mut cfg = defaults();
        cfg.insert("widget_plate".into(), r[0].clone());
        let got = cell_fill(&cfg, r[1].as_bool().unwrap(), r[2].as_i64().unwrap() == 1);
        assert_eq!(json!(got), r[3], "{r}");
    }
    for r in m["tip"].as_array().unwrap() {
        let a = |i: usize| -> Vec<f64> { r[i].as_array().unwrap().iter().map(f).collect() };
        let (w, sz, sc) = (a(0), a(2), a(3));
        let (x, y) = tip_position(
            (w[0], w[1], w[2], w[3]),
            f(&r[1]),
            (sz[0], sz[1]),
            (sc[0], sc[1]),
            8.0,
        );
        assert_eq!(json!([x, y]), r[4], "{r}");
    }
    for r in m["font_opacity"].as_array().unwrap() {
        let mut cfg = defaults();
        cfg.insert("widget_font".into(), r[0].clone());
        cfg.insert("widget_opacity".into(), r[0].clone());
        assert!((font_scale(&cfg) - f(&r[1])).abs() < 1e-12, "{r}");
        assert_eq!(opacity_alpha(&cfg) as i64, r[2].as_i64().unwrap(), "{r}");
    }
}
